"179 :   private boolean tryReplaceArguments(Scope scope) {
180 : 
181 :     Node parametersList = scope.getRootNode().getFirstChild().getNext();
182 :     Preconditions.checkState(parametersList.getType() == Token.LP);
183 : 
184 :     // Keep track of rather this function modified the AST and needs to be
185 :     // reported back to the compiler later.
186 :     boolean changed = false;
187 : 
188 :     // Number of parameter that can be accessed without using the arguments
189 :     // array.
190 :     int numNamedParameter = parametersList.getChildCount();
191 : 
192 :     // We want to guess what the highest index that has been access from the
193 :     // arguments array. We will guess that it does not use anything index higher
194 :     // than the named parameter list first until we see other wise.
195 :     int highestIndex = numNamedParameter - 1;
196 : 
197 :     // Iterate through all the references to arguments array in the function to
198 :     // determine the real highestIndex.
199 :     for (Node ref : currentArgumentsAccess) {
200 : 
201 :       Node getElem = ref.getParent();
202 :       
203 :       // Bail on anything but argument[c] access where c is a constant.
204 :       // TODO(user): We might not need to bail out all the time, there might
205 :       // be more cases that we can cover.
206 :       if (getElem.getType() != Token.GETELEM) {
207 :         return false;
208 :       }
209 : 
210 :       Node index = ref.getNext();
211 : 
212 :       // We have something like arguments[x] where x is not a constant. That
213 :       // means at least one of the access is not known.
214 :       if (index.getType() != Token.NUMBER) {
215 :         // TODO(user): Its possible not to give up just yet. The type
216 :         // inference did a 'semi value propagation'. If we know that string
217 :         // is never a subclass of the type of the index. We'd know that
218 :         // it is never 'callee'.
219 :         return false; // Give up.
220 :       }
221 :       
222 :       Node getElemParent = getElem.getParent();
223 :       // When we have argument[0](), replacing it with a() is semantically
224 :       // different if argument[0] is a function call that refers to 'this'
225 :       if (NodeUtil.isCall(getElemParent) &&
226 :           getElemParent.getFirstChild() == getElem) {
227 :         // TODO(user): We can consider using .call() if aliasing that
228 :         // argument allows shorter alias for other arguments.
229 :         return false;
230 :       }
231 : 
232 :       // Replace the highest index if we see an access that has a higher index
233 :       // than all the one we saw before.
234 :       int value = (int) index.getDouble();
235 :       if (value > highestIndex) {
236 :         highestIndex = value;
237 :       }
238 :     }
239 : 
240 :     // Number of extra arguments we need.
241 :     // For example: function() { arguments[3] } access index 3 so
242 :     // it will need 4 extra named arguments to changed into:
243 :     // function(a,b,c,d) { d }.
244 :     int numExtraArgs = highestIndex - numNamedParameter + 1;
245 : 
246 :     // Temporary holds the new names as string for quick access later.
247 :     String[] argNames = new String[numExtraArgs];
248 : 
249 :     // Insert the formal parameter to the method's signature.
250 :     // Example: function() --> function(r0, r1, r2)
251 :     for (int i = 0; i < numExtraArgs; i++) {
252 :       String name = getNewName();
253 :       argNames[i] = name;
254 :       parametersList.addChildrenToBack(Node.newString(Token.NAME, name));
255 :       changed = true;
256 :     }
257 : 
258 :     // This loop performs the replacement of arguments[x] -> a if x is known.
259 :     for (Node ref : currentArgumentsAccess) {
260 :       Node index = ref.getNext();
261 : 
262 :       // Skip if it is unknown.
263 :       if (index.getType() != Token.NUMBER) {
264 :         continue;
265 :       }
266 :       int value = (int) index.getDouble();
267 : 
268 :       // Unnamed parameter.
269 :       if (value >= numNamedParameter) {
270 :         ref.getParent().getParent().replaceChild(ref.getParent(),
271 :             Node.newString(Token.NAME, argNames[value - numNamedParameter]));
272 :       } else {
273 : 
274 :         // Here, for no apparent reason, the user is accessing a named parameter
275 :         // with arguments[idx]. We can replace it with the actual name for them.
276 :         Node name = parametersList.getFirstChild();
277 : 
278 :         // This is a linear search for the actual name from the signature.
279 :         // It is not necessary to make this fast because chances are the user
280 :         // will not deliberately write code like this.
281 :         for (int i = 0; i < value; i++) {
282 :           name = name.getNext();
283 :         }
284 :         ref.getParent().getParent().replaceChild(ref.getParent(),
285 :             Node.newString(Token.NAME, name.getString()));
286 :       }
287 :       changed = true;
288 :     }
289 : 
290 :     return changed;
291 :   }"

