151 :   public void visit(NodeTraversal traversal, Node node, Node parent) {
152 :     Preconditions.checkNotNull(traversal);
153 :     Preconditions.checkNotNull(node);
154 : 
155 : 
156 :     // Searches for all the references to the arguments array.
157 : 
158 :     // We don't have an arguments list set up for this scope. This implies we
159 :     // are currently in the global scope so we will not record any arguments
160 :     // array access.
161 :     if (currentArgumentsAccess == null) {
162 :       return;
163 :     }
164 : 
165 :     // Otherwise, we are in a function scope and we should record if the current
166 :     // name is referring to the implicit arguments array.
167 :     if (NodeUtil.isName(node) && ARGUMENTS.equals(node.getString())) {
168 :       currentArgumentsAccess.add(node);
169 :     }
170 :   }"

" 95 :   @Override
 96 :   public void enterScope(NodeTraversal traversal) {
 97 :     Preconditions.checkNotNull(traversal);
 98 : 
 99 :     // This optimization is valid only within a function so we are going to
100 :     // skip over the initial entry to the global scope.
101 :     Node function = traversal.getScopeRoot();
102 :     if (!NodeUtil.isFunction(function)) {
103 :       return;
104 :     }
105 : 
106 :     // Introduces a new access list and stores the access list of the outer
107 :     // scope in the stack if necessary.
108 :     if (currentArgumentsAccess != null) {
109 :       argumentsAccessStack.push(currentArgumentsAccess);
110 :     }
111 :     currentArgumentsAccess = Lists.newLinkedList();
112 :   }"

"114 :   @Override
115 :   public void exitScope(NodeTraversal traversal) {
116 :     Preconditions.checkNotNull(traversal);
117 : 
118 :     // This is the case when we are exiting the global scope where we had never
119 :     // collected argument access list. Since we do not perform this optimization
120 :     // for the global scope, we will skip this exit point.
121 :     if (currentArgumentsAccess == null) {
122 :       return;
123 :     }
124 : 
125 :     // Attempt to replace the argument access and if the AST has been change,
126 :     // report back to the compiler.
127 :     if (tryReplaceArguments(traversal.getScope())) {
128 :       traversal.getCompiler().reportCodeChange();
129 :     }
130 : 
131 :     // After the attempt to replace the arguments. The currentArgumentsAccess
132 :     // is stale and as we exit the Scope, no longer holds all the access to the
133 :     // current scope anymore. We'll pop the access list from the outer scope
134 :     // and set it as currentArgumentsAcess if the outer scope is not the global
135 :     // scope.
136 :     if (!argumentsAccessStack.isEmpty()) {
137 :       currentArgumentsAccess = argumentsAccessStack.pop();
138 :     } else {
139 :       currentArgumentsAccess = null;
140 :     }
141 :   }"

